/** Public independent-index reference, isolated from pilot selection and RPC. */
import {createHash} from 'node:crypto';
import {existsSync,mkdirSync,readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {performance} from 'node:perf_hooks';
import {setTimeout as delay} from 'node:timers/promises';
import {PublicKey} from '@solana/web3.js';
import {canonicalPumpPoolPda} from '../src/sdk.js';
const MIB=1024*1024,dir=resolve('evidence/high-activity-20261028');
const digest=(b:string|Buffer)=>createHash('sha256').update(b).digest('hex');
function need(value:unknown,reason:string):asserts value{if(!value)throw Error(reason);}
const phase=process.argv.includes('--start')?'start':process.argv.includes('--end')?'end':null;need(phase,'START_OR_END_REQUIRED');
const limits=Object.freeze({maximumRequests:phase==='start'?3:13,listingPages:3,maximumOhlcvRequests:10,minimumStartSpacingMs:12000,timeoutMs:8000,maximumElapsedMs:phase==='start'?60000:240000,shutdownReserveMs:5000,perResponseBodyBytes:2*MIB,applicationResponseStopBytes:Math.floor(1.5*MIB),receivedBodyBytes:8*MIB,retainedBytes:2*MIB,oneInFlight:true,maximumRssBytes:256*MIB,noAutomaticRetries:true});
const segment={source:'4aaf6e1',startedAt:'2026-10-28T00:13:53.575Z',expectedEndAt:'2026-10-28T00:43:48.000Z',kind:'isolated frozen experimental interval; reference collection begins later and does not reconstruct a contemporaneous early census'};
const selection=Object.freeze({universe:'all rows from independent current PumpSwap DEX pages1–3 at each pass; retain rejected rows and duplicate positions',eligibility:'canonicalSOL PDA address consistency and indexed creation-age5min–2h at actual receipt; hint only, not onchain support',ranking:'union of independently indexed provisional eligible leads from both passes, descending maximum reported5minute volume, then maximum24hour volume, then pool lexical; never POE-selected or ranked by later OHLC outcome',maximumSelectedPools:10,feesOrExecution:'not established by listing or OHLC',wholeMarketDenominator:false});
mkdirSync(dir,{recursive:true,mode:0o700});const planPath=join(dir,'forward-reference-plan.json');
type Receipt={ordinal:number;purpose:string;url:string;startedAt:string;startedUnixMs:number;finishedAt?:string;elapsedMs?:number;status?:number;bodyBytes:number;uncertainBodyBytes?:number;retainedFile?:string;sha256?:string;responseHeaders?:Record<string,string|null>;error?:string};
const priorPath=resolve('evidence/opportunity-coverage-20261027/cohort-ohlcv-20261027T235506594Z-receipt.json');
let plan:any;
if(phase==='start'){
  need(!existsSync(planPath),'START_PASS_ALREADY_PREPARED_NO_RETRY');const priorBytes=readFileSync(priorPath),prior=JSON.parse(priorBytes.toString());need(prior.completedAt&&Date.now()-Date.parse(prior.completedAt)>120000,'PROVIDER_COOLDOWN');
  plan={schemaVersion:1,createdAt:new Date().toISOString(),segment,selection,prior:{path:priorPath,sha256:digest(priorBytes),requestStarts:prior.cumulativeActualRequestStarts,measuredBodyBytes:prior.cumulativeMeasuredBodyBytes,uncertainBodyBytes:prior.cumulativeUncertainBodyBytes},termsEvidence:'evidence/opportunity-coverage-20261027/reference-raw/official-public-api.html: public freekeyless API10calls/min; own>=12s startspacing',startPhase:null,endPhase:null};writeFileSync(planPath,JSON.stringify(plan,null,2)+'\n',{flag:'wx',mode:0o600});
}else{plan=JSON.parse(readFileSync(planPath,'utf8'));need(plan.startPhase&&!plan.endPhase,'START_MUST_SETTLE_BEFORE_ONE_END_PASS');const previous=JSON.parse(readFileSync(join(dir,plan.startPhase),'utf8'));need(previous.stopReason==='all planned requests completed','PREVIOUS_PASS_REFUSED_NO_AUTOMATIC_CONTINUATION');need(Date.now()-Date.parse(previous.completedAt)>120000,'PROVIDER_COOLDOWN');}
const tag=new Date().toISOString().replace(/[-:.]/g,''),name=`forward-reference-${tag}-${phase}-receipt.json`,receiptPath=join(dir,name),rawDir=join(dir,`forward-reference-${tag}-${phase}-raw`);mkdirSync(rawDir,{mode:0o700});
const baseline=phase==='start'?plan.prior:JSON.parse(readFileSync(join(dir,plan.startPhase),'utf8')).cumulative;
const receipts:Receipt[]=[],startedAt=Date.now(),startedMono=performance.now();let received=0,retained=0,lastStart=-Infinity,stopReason='all planned requests completed';
const record:any={schemaVersion:1,classification:'INDEPENDENT_CURRENT_INDEXED_FORWARD_REFERENCE_LEADS_NOT_MARKET_CENSUS',phase,segment:plan.segment,selection,startedAt:new Date(startedAt).toISOString(),completedAt:null,limits,requests:receipts,rows:[],duplicates:[],selectedOhlcvLeads:[],stopReason:'running',newUsage:{requestStarts:0,measuredBodyBytes:0,uncertainBodyBytes:0,retainedBytes:0,elapsedMs:0},cumulative:{requestStarts:baseline.requestStarts,measuredBodyBytes:baseline.measuredBodyBytes,uncertainBodyBytes:baseline.uncertainBodyBytes},limitations:['Listing snapshots reflect actual retrieval times, not market universe at segment start.','Current rank and three-page sampling create coverage, survival, pagination and selection bias.','Canonical PDA and indexed time are scheduling leads, not confirmed migration/current support proof.','Reported price, volume, transaction counts and liquidity are index claims; no trader identities, net buying or actual50USD execution inferred.','API public access has no additional subscription/key cost; infrastructure/transfer allocations remain unverified.'],network:'HTTPS api.geckoterminal.com only; no SolanaRPC, credentials, wallets or pilot writes'};
function checkpoint(){record.newUsage={requestStarts:receipts.length,measuredBodyBytes:received,uncertainBodyBytes:receipts.reduce((n,r)=>n+(r.uncertainBodyBytes??0),0),retainedBytes:retained,elapsedMs:performance.now()-startedMono};record.cumulative={requestStarts:baseline.requestStarts+receipts.length,measuredBodyBytes:baseline.measuredBodyBytes+received,uncertainBodyBytes:baseline.uncertainBodyBytes+record.newUsage.uncertainBodyBytes};const bytes=Buffer.from(JSON.stringify(record,null,2)+'\n');need(retained+bytes.length<=limits.retainedBytes,'RETAINED_CAP');writeFileSync(receiptPath,bytes,{mode:0o600});}
async function get(url:URL,purpose:string,file:string){
  const wait=Math.max(0,lastStart+limits.minimumStartSpacingMs-Date.now());need(performance.now()-startedMono+wait+limits.timeoutMs<limits.maximumElapsedMs-limits.shutdownReserveMs,'TIME_HEADROOM');if(wait)await delay(wait);need(receipts.length<limits.maximumRequests&&received+limits.perResponseBodyBytes<=limits.receivedBodyBytes&&process.memoryUsage().rss<=limits.maximumRssBytes,'RESOURCE_HEADROOM');
  need(url.origin==='https://api.geckoterminal.com'&&url.pathname.startsWith('/api/v2/networks/solana/'),'ENDPOINT_ALLOWLIST');lastStart=Date.now();const r:Receipt={ordinal:receipts.length+1,purpose,url:url.toString(),startedAt:new Date(lastStart).toISOString(),startedUnixMs:lastStart,bodyBytes:0};receipts.push(r);checkpoint();
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),limits.timeoutMs);
  try{const response=await fetch(url,{method:'GET',redirect:'manual',headers:{Accept:'application/json'},signal:controller.signal});r.status=response.status;r.responseHeaders=Object.fromEntries(['date','content-type','content-length','retry-after'].map(k=>[k,response.headers.get(k)]));
    if(response.status!==200){const size=Number(response.headers.get('content-length'));if(Number.isSafeInteger(size)&&size>0)r.uncertainBodyBytes=size;await response.body?.cancel();throw Error(`HTTP_${response.status}_NO_RETRY`);}
    need(response.body,'EMPTY_BODY');const reader=response.body.getReader(),chunks:Buffer[]=[];try{for(;;){const {done,value}=await reader.read();if(done)break;const b=Buffer.from(value);r.bodyBytes+=b.length;received+=b.length;need(r.bodyBytes<=limits.applicationResponseStopBytes&&received<=limits.receivedBodyBytes,'BODY_STOP');chunks.push(b);}}catch(error){controller.abort(error);await reader.cancel().catch(()=>{});throw error;}
    const raw=Buffer.concat(chunks),parsed=JSON.parse(raw.toString('utf8'));need(retained+raw.length+262144<limits.retainedBytes,'EVIDENCE_HEADROOM');const out=join(rawDir,file);need(!existsSync(out),'DUPLICATE_FILE');writeFileSync(out,raw,{mode:0o600});retained+=raw.length;r.retainedFile=out.slice(dir.length+1);r.sha256=digest(raw);return {parsed,receipt:r};
  }catch(error){r.error=error instanceof Error?error.message:'unknown failure';throw error;}finally{clearTimeout(timer);r.finishedAt=new Date().toISOString();r.elapsedMs=Date.now()-r.startedUnixMs;checkpoint();}
}
function normalizePool(pool:any,page:number,position:number,at:number){
  need(pool&&pool.type==='pool'&&pool.attributes&&pool.relationships,'INDEX_ROW_SHAPE');const a=pool.attributes,mint=pool.relationships.base_token?.data?.id?.replace(/^solana_/,''),quote=pool.relationships.quote_token?.data?.id?.replace(/^solana_/,''),created=Date.parse(a.pool_created_at);let canonical:string|null=null,valid=false;
  try{valid=new PublicKey(mint).toBase58()===mint&&new PublicKey(quote).toBase58()===quote&&new PublicKey(a.address).toBase58()===a.address;canonical=canonicalPumpPoolPda(new PublicKey(mint)).toBase58();}catch{}
  const age=at-created,eligible=valid&&canonical===a.address&&quote==='So11111111111111111111111111111111111111112'&&Number.isFinite(created)&&age>=300000&&age<7200000;
  return {page,position,indexedPoolId:pool.id,pool:a.address,mint,quoteMint:quote,name:a.name,indexedCreatedAt:a.pool_created_at,observedAt:new Date(at).toISOString(),ageAtReceiptMs:Number.isFinite(created)?age:null,canonicalAddressMatch:canonical===a.address,SOLQuoted:quote==='So11111111111111111111111111111111111111112',derivedCanonicalPool:canonical,provisionallyEntryAgeEligible:eligible,classification:!valid?'INVALID_ADDRESS':quote!=='So11111111111111111111111111111111111111112'?'OUTSIDE_SOL_QUOTE':canonical!==a.address?'NONCANONICAL_ADDRESS':!eligible?'OUTSIDE_INDEXED_ENTRY_AGE':'ELIGIBLE_INDEXED_LEAD_NEEDS_CHAIN_PROOF',reportedVolumeUsd:a.volume_usd,reportedPriceChanges:a.price_change_percentage,reportedTransactions:a.transactions,reportedCurrentReserveUsd:a.reserve_in_usd};
}
try{
  checkpoint();for(let page=1;page<=3;page++){
    const url=new URL('https://api.geckoterminal.com/api/v2/networks/solana/dexes/pumpswap/pools');url.search=new URLSearchParams({page:String(page),sort:'h24_volume_usd_desc',include:'base_token,quote_token'}).toString();const result=await get(url,`listing-page-${page}`,`page-${page}.json`);need(Array.isArray(result.parsed.data)&&result.parsed.data.length<=20,'INDEX_PAGE_SHAPE');
    for(const [index,pool]of result.parsed.data.entries()){const row=normalizePool(pool,page,index+1,Date.parse(result.receipt.finishedAt!));if(record.rows.some((old:any)=>old.pool===row.pool))record.duplicates.push(row);else record.rows.push(row);}checkpoint();
  }
  if(phase==='end'){
    const endIndex=process.argv.indexOf('--segment-end');need(endIndex>=0&&Number.isFinite(Date.parse(process.argv[endIndex+1]!)),'ACTUAL_SEGMENT_END_REQUIRED');const segmentEnd=Date.parse(process.argv[endIndex+1]!);need(segmentEnd<=Date.now()&&segmentEnd>Date.parse(plan.segment.startedAt),'ACTUAL_SEGMENT_END');record.actualSegmentEndAt=new Date(segmentEnd).toISOString();
    const startRecord=JSON.parse(readFileSync(join(dir,plan.startPhase),'utf8')),all=[...startRecord.rows,...record.rows],union=new Map<string,any>();
    for(const row of all){if(!row.provisionallyEntryAgeEligible)continue;const old=union.get(row.pool);if(!old)union.set(row.pool,{...row,maximumM5VolumeUsd:Number(row.reportedVolumeUsd?.m5??0),maximumH24VolumeUsd:Number(row.reportedVolumeUsd?.h24??0)});else{old.maximumM5VolumeUsd=Math.max(old.maximumM5VolumeUsd,Number(row.reportedVolumeUsd?.m5??0));old.maximumH24VolumeUsd=Math.max(old.maximumH24VolumeUsd,Number(row.reportedVolumeUsd?.h24??0));}}
    record.selectedOhlcvLeads=[...union.values()].sort((a,b)=>b.maximumM5VolumeUsd-a.maximumM5VolumeUsd||b.maximumH24VolumeUsd-a.maximumH24VolumeUsd||a.pool.localeCompare(b.pool)).slice(0,10);
    for(const lead of record.selectedOhlcvLeads){const url=new URL(`https://api.geckoterminal.com/api/v2/networks/solana/pools/${lead.pool}/ohlcv/minute`);url.search=new URLSearchParams({aggregate:'1',before_timestamp:String(Math.floor(segmentEnd/1000)),limit:'1000',currency:'usd',token:lead.mint,include_empty_intervals:'false'}).toString();const {parsed}=await get(url,`selected-ohlcv-${lead.mint}`,`ohlcv-${lead.mint}.json`);need(parsed.meta?.base?.address===lead.mint&&parsed.meta?.quote?.address==='So11111111111111111111111111111111111111112'&&Array.isArray(parsed.data?.attributes?.ohlcv_list),'OHLC_IDENTITY_SHAPE');}
  }
}catch(error){stopReason=error instanceof Error?error.message:'unknown failure';}
record.stopReason=stopReason;record.completedAt=new Date().toISOString();checkpoint();plan[phase==='start'?'startPhase':'endPhase']=name;writeFileSync(planPath,JSON.stringify(plan,null,2)+'\n',{mode:0o600});console.log(JSON.stringify({receipt:name,phase,stopReason,usage:record.newUsage,uniqueRows:record.rows.length,eligibleLeads:record.rows.filter((x:any)=>x.provisionallyEntryAgeEligible).map((x:any)=>({name:x.name,mint:x.mint,pool:x.pool})),selectedOhlcvLeads:record.selectedOhlcvLeads.length}));
